arguments.command:
curl -s -X POST https://api.linear.app/graphql -H "Authorization: Bearer <TOKEN>" -H "Content-Type: application/json" -d '{"query":"{ __type(name: \"Query\") { fields { name args { name type { kind name ofType { kind name ofType { kind name ofType { kind name } } } } } } } }"}' | python3 -c "
import json,sys
d=json.load(sys.stdin)
def fmt(t):
    if t is None: return None
    if t.get('kind')=='NON_NULL': return fmt(t.get('ofType'))+'!'
    if t.get('kind')=='LIST': return '['+fmt(t.get('ofType'))+']'
    return t.get('name')
for f in d['data']['__type']['fields']:
    if f['name']=='semanticSearch':
        print([(a['name'], fmt(a['type'])) for a in f['args']])
"

